-- R3D-7: independent bot-owned business plugins. No prior migration changes.
CREATE TABLE broadcast_campaigns(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL,bot_id uuid NOT NULL,name text NOT NULL CHECK(length(name) BETWEEN 1 AND 100),definition jsonb NOT NULL CHECK(octet_length(definition::text)<=32768),revision bigint NOT NULL DEFAULT 1,state text NOT NULL DEFAULT 'DRAFT' CHECK(state IN('DRAFT','SCHEDULED','RUNNING','PAUSED','COMPLETED','FAILED','CANCELLED')),scheduled_at timestamptz,snapshot_at timestamptz,completed_at timestamptz,UNIQUE(id,workspace_id,bot_id),FOREIGN KEY(bot_id,workspace_id) REFERENCES customer_bots(id,workspace_id));
CREATE INDEX broadcast_campaigns_search ON broadcast_campaigns USING spgist(lower(name));
CREATE TABLE form_definitions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL,bot_id uuid NOT NULL,name text NOT NULL CHECK(length(name) BETWEEN 1 AND 100),definition jsonb NOT NULL CHECK(octet_length(definition::text)<=32768),revision bigint NOT NULL DEFAULT 1,UNIQUE(id,workspace_id,bot_id),FOREIGN KEY(bot_id,workspace_id) REFERENCES customer_bots(id,workspace_id));
CREATE INDEX form_definitions_search ON form_definitions USING spgist(lower(name));
CREATE TABLE commerce_products(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL,bot_id uuid NOT NULL,name text NOT NULL CHECK(length(name) BETWEEN 1 AND 100),definition jsonb NOT NULL CHECK(octet_length(definition::text)<=32768),revision bigint NOT NULL DEFAULT 1,UNIQUE(id,workspace_id,bot_id),FOREIGN KEY(bot_id,workspace_id) REFERENCES customer_bots(id,workspace_id));
CREATE INDEX commerce_products_search ON commerce_products USING spgist(lower(name));
CREATE TABLE business_operations(workspace_id uuid NOT NULL,bot_id uuid NOT NULL,plugin_id text NOT NULL CHECK(plugin_id IN('broadcast','forms','commerce')),operation_key text NOT NULL CHECK(length(operation_key) BETWEEN 1 AND 100),fingerprint text NOT NULL,result jsonb NOT NULL,PRIMARY KEY(bot_id,plugin_id,operation_key),FOREIGN KEY(bot_id,workspace_id) REFERENCES customer_bots(id,workspace_id));
CREATE TABLE plugin_broadcast_recipients(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL,bot_id uuid NOT NULL,campaign_id uuid NOT NULL,contact_id uuid NOT NULL,telegram_id bigint NOT NULL CHECK(telegram_id>0),ordinal int NOT NULL CHECK(ordinal>=0),state text NOT NULL DEFAULT 'QUEUED' CHECK(state IN('QUEUED','SENDING','SENT','FAILED','UNKNOWN','SKIPPED','CANCELLED')),attempt int NOT NULL DEFAULT 0 CHECK(attempt BETWEEN 0 AND 3),available_at timestamptz NOT NULL,lease_until timestamptz,code text NOT NULL DEFAULT '',message_id bigint,UNIQUE(campaign_id,contact_id),UNIQUE(campaign_id,telegram_id),UNIQUE(campaign_id,ordinal),FOREIGN KEY(campaign_id,workspace_id,bot_id) REFERENCES broadcast_campaigns(id,workspace_id,bot_id),FOREIGN KEY(contact_id,workspace_id,bot_id) REFERENCES crm_contacts(id,workspace_id,bot_id));
CREATE INDEX broadcast_dispatch ON plugin_broadcast_recipients(workspace_id,bot_id,state,available_at,ordinal);
CREATE TABLE broadcast_rate(workspace_id uuid NOT NULL,bot_id uuid PRIMARY KEY,next_at timestamptz NOT NULL,FOREIGN KEY(bot_id,workspace_id) REFERENCES customer_bots(id,workspace_id));
CREATE TABLE form_submissions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL,bot_id uuid NOT NULL,form_id uuid NOT NULL,contact_id uuid NOT NULL,form_revision bigint NOT NULL,snapshot jsonb NOT NULL,answers jsonb NOT NULL CHECK(octet_length(answers::text)<=16384),created_at timestamptz NOT NULL,FOREIGN KEY(form_id,workspace_id,bot_id) REFERENCES form_definitions(id,workspace_id,bot_id),FOREIGN KEY(contact_id,workspace_id,bot_id) REFERENCES crm_contacts(id,workspace_id,bot_id));
CREATE TABLE commerce_orders(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL,bot_id uuid NOT NULL,contact_id uuid NOT NULL,state text NOT NULL CHECK(state IN('DRAFT','PLACED','CONFIRMED','FULFILLED','CANCELLED')),lines jsonb NOT NULL,total jsonb NOT NULL,revision bigint NOT NULL DEFAULT 1,created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL,UNIQUE(id,workspace_id,bot_id),FOREIGN KEY(bot_id,workspace_id) REFERENCES customer_bots(id,workspace_id),FOREIGN KEY(contact_id,workspace_id,bot_id) REFERENCES crm_contacts(id,workspace_id,bot_id));
CREATE TABLE commerce_order_history(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL,bot_id uuid NOT NULL,order_id uuid NOT NULL,actor_id uuid NOT NULL,state text NOT NULL,revision bigint NOT NULL,created_at timestamptz NOT NULL,UNIQUE(order_id,revision),FOREIGN KEY(order_id,workspace_id,bot_id) REFERENCES commerce_orders(id,workspace_id,bot_id),FOREIGN KEY(workspace_id,actor_id) REFERENCES workspace_members(workspace_id,user_id));
CREATE UNIQUE INDEX business_telegram_replay ON business_operations(bot_id,operation_key) WHERE operation_key LIKE 'telegram:%';
CREATE TABLE broadcast_campaign_history(workspace_id uuid NOT NULL,bot_id uuid NOT NULL,campaign_id uuid NOT NULL,revision bigint NOT NULL,state text NOT NULL,created_at timestamptz NOT NULL,PRIMARY KEY(campaign_id,revision),FOREIGN KEY(campaign_id,workspace_id,bot_id) REFERENCES broadcast_campaigns(id,workspace_id,bot_id));
CREATE FUNCTION guard_business_retention() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'business data retained pending explicit retention policy'; END IF;
 IF NEW.workspace_id<>OLD.workspace_id OR NEW.bot_id<>OLD.bot_id THEN RAISE EXCEPTION 'business scope immutable'; END IF;
 IF TG_TABLE_NAME IN('business_operations','form_submissions','commerce_order_history','broadcast_campaign_history') THEN RAISE EXCEPTION 'business history immutable'; END IF;
 IF TG_TABLE_NAME IN('broadcast_campaigns','form_definitions','commerce_products','commerce_orders') THEN
 IF NEW.revision<>OLD.revision+1 THEN RAISE EXCEPTION 'business revision invalid'; END IF; END IF;
 IF TG_TABLE_NAME='broadcast_campaigns' THEN
  IF OLD.state<>'DRAFT' AND (NEW.definition<>OLD.definition OR NEW.snapshot_at IS DISTINCT FROM OLD.snapshot_at OR NEW.scheduled_at IS DISTINCT FROM OLD.scheduled_at) THEN RAISE EXCEPTION 'campaign snapshot immutable'; END IF;
  IF NEW.state<>OLD.state AND NOT((OLD.state='DRAFT' AND NEW.state IN('SCHEDULED','CANCELLED')) OR (OLD.state='SCHEDULED' AND NEW.state IN('RUNNING','PAUSED','CANCELLED','COMPLETED','FAILED')) OR (OLD.state='RUNNING' AND NEW.state IN('PAUSED','COMPLETED','FAILED','CANCELLED')) OR (OLD.state='PAUSED' AND NEW.state IN('SCHEDULED','CANCELLED'))) THEN RAISE EXCEPTION 'campaign transition invalid'; END IF;
 END IF;
 IF TG_TABLE_NAME='commerce_orders' THEN
  IF NEW.lines<>OLD.lines OR NEW.total<>OLD.total OR NEW.contact_id<>OLD.contact_id THEN RAISE EXCEPTION 'order price snapshot immutable'; END IF;
  IF NOT((OLD.state='DRAFT' AND NEW.state IN('PLACED','CANCELLED')) OR (OLD.state='PLACED' AND NEW.state IN('CONFIRMED','CANCELLED')) OR (OLD.state='CONFIRMED' AND NEW.state IN('FULFILLED','CANCELLED'))) THEN RAISE EXCEPTION 'order transition invalid'; END IF;
 END IF;
 IF TG_TABLE_NAME='plugin_broadcast_recipients' THEN
  IF NEW.campaign_id<>OLD.campaign_id OR NEW.contact_id<>OLD.contact_id OR NEW.telegram_id<>OLD.telegram_id OR NEW.ordinal<>OLD.ordinal THEN RAISE EXCEPTION 'recipient snapshot immutable'; END IF;
  IF OLD.state IN('SENT','FAILED','UNKNOWN','SKIPPED','CANCELLED') THEN RAISE EXCEPTION 'recipient terminal state immutable'; END IF;
 END IF;
 RETURN NEW;END $$;
DO $$ DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['broadcast_campaigns','form_definitions','commerce_products','business_operations','plugin_broadcast_recipients','broadcast_rate','form_submissions','commerce_orders','commerce_order_history','broadcast_campaign_history'] LOOP
 EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',t);
 EXECUTE format('CREATE POLICY tenant_scope ON %I USING(workspace_id::text=current_setting(''app.workspace_id'',true)) WITH CHECK(workspace_id::text=current_setting(''app.workspace_id'',true))',t);
 EXECUTE format('CREATE TRIGGER business_guard BEFORE UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION guard_business_retention()',t);
END LOOP;END $$;
INSERT INTO permissions(key) VALUES('broadcast.manage'),('forms.manage'),('commerce.manage');
INSERT INTO role_permissions(role_key,permission_key) SELECT r,p FROM (VALUES('OWNER'),('ADMIN')) a(r) CROSS JOIN (VALUES('broadcast.manage'),('forms.manage'),('commerce.manage')) b(p);
INSERT INTO commercial_catalog(kind,key,version,enabled,effective_at,definition,reason)
 SELECT 'PLUGIN',key,1,true,'2020-01-01T00:00:00Z',jsonb_build_object('plugin',jsonb_build_object('capabilities',caps,'sale_enabled',false,'scope','PER_BOT','prices',jsonb_build_object('daily',jsonb_build_object('unit','USD','scale',2,'amount','0'),'monthly',jsonb_build_object('unit','USD','scale',2,'amount','0')),'trial',jsonb_build_object('enabled',false,'duration_seconds',0),'grace_seconds',0)), 'R3D-7 configure before sale; no automatic grants'
 FROM (VALUES('broadcast','["broadcast.manage","telegram.send","crm.read"]'::jsonb),('forms','["forms.manage","forms.submit","crm.write"]'::jsonb),('commerce','["commerce.manage","commerce.order","crm.write"]'::jsonb)) p(key,caps);
INSERT INTO commercial_catalog(kind,key,version,enabled,effective_at,definition,reason)
 SELECT 'QUOTA',key,1,true,'2020-01-01T00:00:00Z',jsonb_build_object('quota',jsonb_build_object('scope','PER_BOT','reset',period,'default',jsonb_build_object('value','0','unlimited',true))), 'R3D-7 configurable quota'
 FROM (VALUES('broadcast.definitions.count','NONE'),('broadcast.recipients.count','NONE'),('broadcast.messages.monthly','MONTHLY'),('forms.definitions.count','NONE'),('forms.submissions.monthly','MONTHLY'),('commerce.definitions.count','NONE'),('commerce.orders.monthly','MONTHLY')) q(key,period);
